#!/usr/bin/env tsx
/**
 * Render `docs/agent-map.html` from an AgentGraph.
 *
 * Apple-style **connection stage** — agents and how they wire together.
 * Not a marketing landing. Not a spaghetti DAG. Light Telivity craft
 * (Montserrat, teal #06bdb4, navy #23273d, fog #f0f0f6).
 * Generated by `pnpm gen:manifest` / `pnpm gen:agent-map`.
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { AgentGraph, AgentGraphEdge, AgentGraphNode } from './agent-graph.js';

const GRAPH_PATH = 'agents.graph.json';
const MAP_HTML_PATH = 'docs/agent-map.html';

const STAGE_ORDER = [
  'reference',
  'search',
  'pricing',
  'booking',
  'ticketing',
  'exchange',
  'settlement',
  'reconciliation',
  'tmc',
  'platform',
  'core',
  'lodging',
] as const;

const STAGE_DISPLAY: Readonly<Record<string, string>> = {
  reference: 'Reference',
  search: 'Search',
  pricing: 'Pricing',
  booking: 'Booking',
  ticketing: 'Ticketing',
  exchange: 'Exchange',
  settlement: 'Settlement',
  reconciliation: 'Reconciliation',
  tmc: 'TMC',
  platform: 'Platform',
  core: 'Core',
  lodging: 'Lodging',
};

const BENTO_SPAN: Readonly<Record<string, string>> = {
  search: 'span-3',
  pricing: 'span-3',
  booking: 'span-4',
  ticketing: 'span-2',
  exchange: 'span-2',
  settlement: 'span-2',
  reconciliation: 'span-2',
  reference: 'span-2',
  tmc: 'span-2',
  core: 'span-2',
  lodging: 'span-3',
  platform: 'span-3',
};

function repoRoot(): string {
  let cur = dirname(fileURLToPath(import.meta.url));
  for (let i = 0; i < 8; i++) {
    if (existsSync(join(cur, 'pnpm-workspace.yaml'))) return cur;
    const parent = dirname(cur);
    if (parent === cur) break;
    cur = parent;
  }
  return resolve(dirname(fileURLToPath(import.meta.url)), '..');
}

function compareAgentIds(a: string, b: string): number {
  const [aMajor = 0, aMinor = 0] = a.split('.').map(Number);
  const [bMajor = 0, bMinor = 0] = b.split('.').map(Number);
  return aMajor - bMajor || aMinor - bMinor || a.localeCompare(b);
}

function stageSortKey(stage: string): number {
  const idx = (STAGE_ORDER as readonly string[]).indexOf(stage);
  return idx === -1 ? 1000 : idx;
}

function stageDisplay(stage: string): string {
  return STAGE_DISPLAY[stage] ?? stage.charAt(0).toUpperCase() + stage.slice(1);
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function groupByStage(nodes: readonly AgentGraphNode[]): Array<[string, AgentGraphNode[]]> {
  const map = new Map<string, AgentGraphNode[]>();
  for (const n of nodes) {
    const list = map.get(n.stage) ?? [];
    list.push(n);
    map.set(n.stage, list);
  }
  for (const list of map.values()) {
    list.sort((a, b) => compareAgentIds(a.id, b.id));
  }
  return [...map.entries()].sort(([a], [b]) => stageSortKey(a) - stageSortKey(b) || a.localeCompare(b));
}

/** Ordered agent ids for a workflow from its directed edges. */
export function workflowChain(edges: readonly AgentGraphEdge[], label: string): string[] {
  const wf = edges.filter((e) => e.kind === 'workflow' && e.label === label);
  if (wf.length === 0) return [];
  const outs = new Map<string, string[]>();
  const ins = new Map<string, number>();
  const nodes = new Set<string>();
  for (const e of wf) {
    nodes.add(e.source);
    nodes.add(e.target);
    const list = outs.get(e.source) ?? [];
    list.push(e.target);
    outs.set(e.source, list);
    ins.set(e.target, (ins.get(e.target) ?? 0) + 1);
    if (!ins.has(e.source)) ins.set(e.source, ins.get(e.source) ?? 0);
  }
  const starts = [...nodes].filter((n) => (ins.get(n) ?? 0) === 0).sort(compareAgentIds);
  const chain: string[] = [];
  const seen = new Set<string>();
  const queue = [...starts];
  while (queue.length) {
    const id = queue.shift();
    if (!id || seen.has(id)) continue;
    seen.add(id);
    chain.push(id);
    for (const t of outs.get(id) ?? []) {
      if (!seen.has(t)) queue.push(t);
    }
  }
  for (const n of [...nodes].sort(compareAgentIds)) {
    if (!seen.has(n)) chain.push(n);
  }
  return chain;
}

function workflowLabels(graph: AgentGraph): string[] {
  return [
    ...new Set(graph.edges.filter((e) => e.kind === 'workflow').map((e) => e.label)),
  ].sort((a, b) => {
    if (a === 'full_booking') return -1;
    if (b === 'full_booking') return 1;
    return a.localeCompare(b);
  });
}

export function renderAgentMapHtml(graph: AgentGraph): string {
  const stages = groupByStage(graph.nodes);
  const workflows = workflowLabels(graph);
  const defaultWf = workflows.includes('full_booking') ? 'full_booking' : (workflows[0] ?? '');
  const nodesById = Object.fromEntries(graph.nodes.map((n) => [n.id, n]));

  const wfMeta = Object.fromEntries(
    workflows.map((w) => {
      const chain = workflowChain(graph.edges, w);
      return [w, { chain, count: chain.length }];
    }),
  );

  const stageTiles = stages
    .map(([stage, agents], idx) => {
      const span = BENTO_SPAN[stage] ?? 'span-2';
      const num = String(idx + 1).padStart(2, '0');
      const rows = agents
        .map(
          (a) => `            <button type="button" class="agent-row" data-id="${escapeHtml(a.id)}" data-stage="${escapeHtml(a.stage)}" data-status="${escapeHtml(a.contract_status)}">
              <span class="dot ${a.contract_status === 'active' ? 'on' : ''}"></span>
              <span class="aid">${escapeHtml(a.id)}</span>
              <span class="aname">${escapeHtml(a.name)}</span>
            </button>`,
        )
        .join('\n');
      const preview = agents
        .slice(0, 2)
        .map((a) => a.name)
        .join(' · ');
      const more = agents.length > 2 ? ` · +${agents.length - 2}` : '';
      return `        <article class="tile ${span}" data-stage="${escapeHtml(stage)}" style="--n:'${num}'">
          <button type="button" class="tile-head" aria-expanded="false">
            <span class="tile-stage">${escapeHtml(stageDisplay(stage))}</span>
            <span class="tile-count">${agents.length}</span>
            <span class="tile-preview">${escapeHtml(preview)}${escapeHtml(more)}</span>
            <span class="chev" aria-hidden="true"></span>
          </button>
          <div class="tile-body">
${rows}
          </div>
        </article>`;
    })
    .join('\n');

  const wfSegs = workflows
    .map((w) => {
      const meta = wfMeta[w]!;
      const active = w === defaultWf ? ' active' : '';
      return `        <button type="button" class="wf-seg${active}" data-workflow="${escapeHtml(w)}" aria-pressed="${w === defaultWf ? 'true' : 'false'}">
          <span class="wf-name">${escapeHtml(w)}</span>
          <span class="wf-n">${meta.count}</span>
        </button>`;
    })
    .join('\n');

  const payload = JSON.stringify({
    nodes: graph.nodes,
    edges: graph.edges,
    workflows: wfMeta,
    defaultWorkflow: defaultWf,
    stages: Object.fromEntries(stages.map(([s, a]) => [s, a.map((x) => x.id)])),
  });

  // Seed stage HTML for default workflow (JS will re-render)
  const seedChain = defaultWf ? workflowChain(graph.edges, defaultWf) : [];
  const seedStage = seedChain
    .map((id, i) => {
      const n = nodesById[id];
      if (!n) return '';
      const conn =
        i < seedChain.length - 1
          ? `<div class="conn" aria-hidden="true"><span class="conn-line"></span><span class="conn-arrow"></span></div>`
          : '';
      return `        <div class="chain-item" style="--i:${i}">
          <button type="button" class="chain-card" data-id="${escapeHtml(id)}">
            <span class="c-step">${String(i + 1).padStart(2, '0')}</span>
            <span class="c-id">${escapeHtml(id)}</span>
            <span class="c-name">${escapeHtml(n.name)}</span>
            <span class="c-stage">${escapeHtml(stageDisplay(n.stage))}</span>
          </button>
          ${conn}
        </div>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Agent connections · Telivity Otaip</title>
  <meta name="description" content="How Otaip agents connect — workflows and package dependencies." />
  <link rel="icon" href="assets/telivity/favicon.ico" sizes="any" />
  <link rel="icon" href="assets/telivity/favicon.svg" type="image/svg+xml" />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;600;700&display=swap" rel="stylesheet" />
  <style>
    :root {
      --teal: #06bdb4;
      --teal-dark: #00a692;
      --teal-light: #2cd1b9;
      --navy: #23273d;
      --slate: #444863;
      --mid: #bbbbc4;
      --fog: #f0f0f6;
      --white: #ffffff;
      --yellow: #eec517;
      --ink: var(--navy);
      --muted: #6b7088;
      --hair: rgba(68, 72, 99, 0.14);
      --hair-strong: rgba(68, 72, 99, 0.22);
      --teal-soft: rgba(6, 189, 180, 0.12);
      --teal-glow: rgba(6, 189, 180, 0.28);
      --shadow: 0 1px 2px rgba(35,39,61,0.04), 0 8px 24px rgba(35,39,61,0.06);
      --shadow-lift: 0 2px 4px rgba(35,39,61,0.05), 0 16px 40px rgba(35,39,61,0.10);
      --font: "Montserrat", system-ui, sans-serif;
      --mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
      --radius: 14px;
      --radius-sm: 10px;
    }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: var(--font);
      color: var(--ink);
      background: var(--fog);
      -webkit-font-smoothing: antialiased;
      min-height: 100%;
    }
    button, input, select { font: inherit; }
    a { color: var(--teal-dark); text-decoration: none; }
    a:hover { text-decoration: underline; }

    /* —— chrome —— */
    .bar {
      position: sticky; top: 0; z-index: 40;
      display: flex; align-items: center; gap: 0.75rem;
      padding: 0.7rem 1.5rem;
      background: rgba(240, 240, 246, 0.82);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid transparent;
      transition: border-color .2s;
    }
    .bar.scrolled { border-bottom-color: var(--hair); }
    .bar-brand {
      display: inline-flex; align-items: center; gap: 0.5rem;
      color: var(--ink); text-decoration: none; font-weight: 700; font-size: 0.95rem;
      letter-spacing: -0.02em;
    }
    .bar-brand:hover { text-decoration: none; opacity: 0.85; }
    .bar-brand img { width: 22px; height: 22px; display: block; }
    .bar-title {
      font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em;
      text-transform: uppercase; color: var(--muted);
      padding-left: 0.75rem; border-left: 1px solid var(--hair-strong);
    }
    .bar-meta {
      margin-left: auto;
      font-family: var(--mono); font-size: 0.68rem; color: var(--muted);
      letter-spacing: 0.02em;
    }

    .shell { max-width: 1280px; margin: 0 auto; padding: 0 1.5rem 4rem; }

    /* —— connection stage (first viewport drama) —— */
    .stage-wrap {
      padding: 1.75rem 0 2.5rem;
      min-height: calc(100vh - 3.5rem);
      display: flex; flex-direction: column; gap: 1.5rem;
    }
    .stage-head {
      display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between;
      gap: 1rem 2rem;
    }
    .stage-head h1 {
      margin: 0;
      font-size: clamp(2.4rem, 5.5vw, 3.75rem);
      font-weight: 700; letter-spacing: -0.045em; line-height: 1.05;
      color: var(--ink);
    }
    .stage-head h1 em {
      font-style: normal;
      background: linear-gradient(100deg, var(--teal-dark), var(--teal) 55%, var(--teal-light));
      -webkit-background-clip: text; background-clip: text; color: transparent;
    }
    .stage-sub {
      margin: 0.45rem 0 0;
      color: var(--muted); font-size: 0.95rem; font-weight: 400;
      max-width: 28rem; line-height: 1.45;
    }

    .wf-picker {
      display: flex; flex-wrap: wrap; gap: 0.4rem;
      padding: 0.35rem;
      background: var(--white);
      border: 1px solid var(--hair);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      align-self: start;
    }
    .wf-seg {
      border: 1px solid transparent;
      background: transparent;
      color: var(--muted);
      border-radius: var(--radius-sm);
      padding: 0.55rem 0.85rem;
      cursor: pointer;
      display: inline-flex; align-items: baseline; gap: 0.45rem;
      transition: background .18s, color .18s, border-color .18s, transform .18s;
    }
    .wf-seg:hover { color: var(--ink); background: rgba(35,39,61,0.03); }
    .wf-seg.active {
      background: var(--navy); color: var(--white);
      box-shadow: 0 4px 14px rgba(35,39,61,0.18);
    }
    .wf-name { font-weight: 600; font-size: 0.78rem; letter-spacing: -0.01em; }
    .wf-n {
      font-family: var(--mono); font-size: 0.62rem; opacity: 0.65;
    }
    .wf-seg.active .wf-n { opacity: 0.8; color: var(--teal-light); }

    .chain-board {
      position: relative;
      flex: 1;
      min-height: 18rem;
      background:
        radial-gradient(900px 420px at 20% 0%, rgba(6,189,180,0.10), transparent 60%),
        radial-gradient(700px 380px at 90% 100%, rgba(238,197,23,0.06), transparent 55%),
        var(--white);
      border: 1px solid var(--hair);
      border-radius: 22px;
      box-shadow: var(--shadow);
      overflow: hidden;
      display: flex; flex-direction: column;
    }
    .chain-board::before {
      content: attr(data-wf);
      position: absolute; right: 1.25rem; bottom: 0.6rem;
      font-size: clamp(3rem, 10vw, 6.5rem); font-weight: 700;
      letter-spacing: -0.06em; line-height: 1;
      color: rgba(35,39,61,0.04); pointer-events: none; user-select: none;
    }
    .chain-label {
      padding: 1rem 1.35rem 0;
      font-size: 0.65rem; font-weight: 600; letter-spacing: 0.12em;
      text-transform: uppercase; color: var(--teal-dark);
    }
    .chain-track {
      display: flex; align-items: stretch; gap: 0;
      padding: 1.25rem 1.35rem 2.5rem;
      overflow-x: auto; scroll-snap-type: x proximity;
      -webkit-overflow-scrolling: touch;
    }
    .chain-item {
      display: flex; align-items: center; flex: 0 0 auto;
      scroll-snap-align: start;
      animation: rise 480ms cubic-bezier(.2,.8,.2,1) both;
      animation-delay: calc(var(--i, 0) * 55ms);
    }
    .chain-card {
      width: 11.5rem; min-height: 9.5rem;
      text-align: left;
      border: 1px solid var(--hair-strong);
      background: linear-gradient(180deg, #fff 0%, #f7f7fb 100%);
      border-radius: 16px;
      padding: 1rem 1rem 0.95rem;
      cursor: pointer;
      display: flex; flex-direction: column; gap: 0.2rem;
      box-shadow: var(--shadow);
      transition: transform .2s, box-shadow .2s, border-color .2s;
      position: relative;
    }
    .chain-card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow-lift);
      border-color: rgba(6,189,180,0.45);
    }
    .chain-card.selected {
      border-color: var(--teal);
      box-shadow: 0 0 0 2px var(--teal-soft), var(--shadow-lift);
    }
    .c-step {
      font-family: var(--mono); font-size: 0.62rem; font-weight: 500;
      letter-spacing: 0.08em; color: var(--teal-dark); margin-bottom: 0.35rem;
    }
    .c-id {
      font-family: var(--mono); font-size: 0.7rem; color: var(--muted);
    }
    .c-name {
      font-size: 0.95rem; font-weight: 700; letter-spacing: -0.025em;
      line-height: 1.25; color: var(--ink); margin-top: 0.15rem;
    }
    .c-stage {
      margin-top: auto; padding-top: 0.65rem;
      font-size: 0.62rem; font-weight: 600; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--mid);
    }

    /* The connection — the star */
    .conn {
      width: 2.6rem; flex: 0 0 auto;
      display: flex; align-items: center; justify-content: center;
      position: relative; height: 100%;
      padding: 0 0.15rem;
    }
    .conn-line {
      display: block; height: 3px; width: 100%;
      background: linear-gradient(90deg, var(--teal-dark), var(--teal-light));
      border-radius: 2px;
      box-shadow: 0 0 12px var(--teal-glow);
      transform-origin: left center;
      animation: draw 700ms cubic-bezier(.2,.8,.2,1) both;
      animation-delay: calc(var(--i, 0) * 55ms + 120ms);
    }
    .conn-arrow {
      position: absolute; right: 0; top: 50%;
      width: 0; height: 0;
      border-top: 5px solid transparent;
      border-bottom: 5px solid transparent;
      border-left: 7px solid var(--teal-light);
      transform: translateY(-50%);
      filter: drop-shadow(0 0 4px var(--teal-glow));
      animation: pop 500ms cubic-bezier(.2,.8,.2,1) both;
      animation-delay: calc(var(--i, 0) * 55ms + 280ms);
    }
    @keyframes draw {
      from { transform: scaleX(0); opacity: 0; }
      to { transform: scaleX(1); opacity: 1; }
    }
    @keyframes pop {
      from { opacity: 0; transform: translateY(-50%) translateX(-4px); }
      to { opacity: 1; transform: translateY(-50%) translateX(0); }
    }
    @keyframes rise {
      from { opacity: 0; transform: translateY(12px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .chain-empty {
      padding: 3rem 1.5rem; color: var(--muted); text-align: center;
    }

    /* —— all agents bento —— */
    .roster { padding: 0.5rem 0 2rem; }
    .roster-head {
      display: flex; flex-wrap: wrap; align-items: end; gap: 1rem;
      margin-bottom: 1.1rem;
    }
    .roster-head h2 {
      margin: 0;
      font-size: clamp(1.6rem, 3.2vw, 2.25rem);
      font-weight: 700; letter-spacing: -0.035em;
    }
    .roster-head p {
      margin: 0.25rem 0 0; color: var(--muted); font-size: 0.88rem;
      width: 100%;
    }
    .controls {
      margin-left: auto;
      display: flex; flex-wrap: wrap; gap: 0.4rem; align-items: center;
    }
    .controls input, .controls select {
      border: 1px solid var(--hair-strong);
      background: var(--white);
      color: var(--ink);
      border-radius: var(--radius-sm);
      padding: 0.45rem 0.65rem;
      font-size: 0.78rem;
    }
    .controls input { min-width: 11rem; font-family: var(--mono); font-size: 0.72rem; }
    .controls input:focus, .controls select:focus {
      outline: none; border-color: var(--teal);
      box-shadow: 0 0 0 3px var(--teal-soft);
    }

    .bento {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 0.75rem;
    }
    @media (max-width: 960px) { .bento { grid-template-columns: repeat(2, 1fr); } }
    @media (max-width: 560px) { .bento { grid-template-columns: 1fr; } }
    .tile { grid-column: span 2; }
    .tile.span-3 { grid-column: span 3; }
    .tile.span-4 { grid-column: span 4; }
    @media (max-width: 960px) {
      .tile, .tile.span-3, .tile.span-4 { grid-column: span 1; }
    }

    .tile {
      position: relative;
      background: var(--white);
      border: 1px solid var(--hair);
      border-radius: 18px;
      box-shadow: var(--shadow);
      overflow: hidden;
      transition: opacity .25s, transform .2s, box-shadow .2s, border-color .2s;
    }
    .tile::after {
      content: var(--n);
      position: absolute; right: 0.6rem; top: 0.2rem;
      font-size: 3.2rem; font-weight: 700; letter-spacing: -0.06em;
      color: rgba(35,39,61,0.045); pointer-events: none; line-height: 1;
    }
    .tile.on-path {
      border-color: rgba(6,189,180,0.55);
      box-shadow: 0 0 0 1px var(--teal-soft), var(--shadow-lift);
    }
    .tile.dim { opacity: 0.38; }
    .tile-head {
      width: 100%; text-align: left; border: 0; background: transparent;
      padding: 1.15rem 1.15rem 1rem; cursor: pointer;
      display: grid; grid-template-columns: 1fr auto; gap: 0.15rem 0.5rem;
      position: relative; z-index: 1;
    }
    .tile-stage {
      font-size: 0.65rem; font-weight: 600; letter-spacing: 0.12em;
      text-transform: uppercase; color: var(--teal-dark);
    }
    .tile-count {
      font-size: 1.85rem; font-weight: 700; letter-spacing: -0.04em;
      grid-column: 1; line-height: 1.1;
    }
    .tile-count::after {
      content: " agents"; font-size: 0.72rem; font-weight: 500;
      letter-spacing: 0; color: var(--muted); margin-left: 0.25rem;
    }
    .tile-preview {
      grid-column: 1 / -1; font-size: 0.72rem; color: var(--muted);
      line-height: 1.35; margin-top: 0.2rem;
    }
    .chev {
      grid-row: 1 / 3; grid-column: 2; align-self: center;
      width: 0.5rem; height: 0.5rem;
      border-right: 2px solid var(--mid); border-bottom: 2px solid var(--mid);
      transform: rotate(45deg); transition: transform .2s;
    }
    .tile.open .chev { transform: rotate(225deg); }
    .tile-body {
      display: none; border-top: 1px solid var(--hair);
      padding: 0.25rem 0;
    }
    .tile.open .tile-body { display: block; }
    .agent-row {
      width: 100%; border: 0; background: transparent; cursor: pointer;
      display: grid; grid-template-columns: 0.6rem 2.4rem 1fr;
      gap: 0.55rem; align-items: center;
      padding: 0.7rem 1.15rem; text-align: left;
      border-bottom: 1px solid var(--hair);
      transition: background .15s;
    }
    .agent-row:last-child { border-bottom: 0; }
    .agent-row:hover { background: rgba(6,189,180,0.06); }
    .agent-row.on-path .aname { color: var(--teal-dark); font-weight: 600; }
    .agent-row.selected {
      background: var(--teal-soft);
    }
    .agent-row.dim { opacity: 0.35; }
    .dot {
      width: 0.45rem; height: 0.45rem; border-radius: 50%;
      background: var(--mid);
    }
    .dot.on { background: var(--teal); box-shadow: 0 0 0 3px var(--teal-soft); }
    .aid { font-family: var(--mono); font-size: 0.68rem; color: var(--muted); }
    .aname { font-size: 0.82rem; font-weight: 500; letter-spacing: -0.01em; }

    /* —— detail panel —— */
    .scrim {
      position: fixed; inset: 0; background: rgba(35,39,61,0.28);
      backdrop-filter: blur(4px); z-index: 50; opacity: 0;
      transition: opacity .25s;
    }
    .scrim.show { opacity: 1; }
    .panel {
      position: fixed; top: 0; right: 0; z-index: 60;
      width: min(22rem, 100%); height: 100%;
      background: var(--white);
      border-left: 1px solid var(--hair);
      box-shadow: -12px 0 40px rgba(35,39,61,0.12);
      transform: translateX(104%);
      transition: transform .32s cubic-bezier(.2,.8,.2,1);
      display: flex; flex-direction: column;
      padding: 1.25rem 1.35rem 2rem;
    }
    .panel.open { transform: translateX(0); }
    .panel-top { display: flex; justify-content: flex-end; margin-bottom: 0.5rem; }
    .panel-x {
      border: 1px solid var(--hair-strong); background: var(--fog);
      border-radius: var(--radius-sm); width: 2rem; height: 2rem;
      cursor: pointer; color: var(--ink); font-size: 1.1rem; line-height: 1;
    }
    .panel .p-id {
      font-family: var(--mono); font-size: 0.72rem; color: var(--teal-dark);
      letter-spacing: 0.04em;
    }
    .panel h3 {
      margin: 0.2rem 0 0.55rem;
      font-size: 1.35rem; font-weight: 700; letter-spacing: -0.03em;
    }
    .badge {
      display: inline-flex; align-items: center; gap: 0.35rem;
      font-size: 0.65rem; font-weight: 600; letter-spacing: 0.08em;
      text-transform: uppercase; color: var(--muted); margin-bottom: 0.85rem;
    }
    .badge i {
      width: 0.45rem; height: 0.45rem; border-radius: 50%;
      background: var(--teal);
    }
    .badge.stub i { background: var(--mid); }
    .panel dl {
      margin: 0; display: grid; grid-template-columns: 5rem 1fr;
      gap: 0.4rem 0.5rem; font-size: 0.78rem;
      padding-top: 0.75rem; border-top: 1px solid var(--hair);
    }
    .panel dt { color: var(--muted); }
    .panel dd { margin: 0; word-break: break-word; }
    .panel code { font-family: var(--mono); font-size: 0.65rem; color: var(--slate); }
    .p-label {
      margin: 1.1rem 0 0.45rem;
      font-size: 0.62rem; font-weight: 600; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--muted);
    }
    .mini-row { display: flex; flex-wrap: wrap; gap: 0.35rem; }
    .mini {
      border: 1px solid var(--hair-strong); background: var(--fog);
      border-radius: 8px; padding: 0.35rem 0.55rem;
      font-size: 0.68rem; font-weight: 600; cursor: pointer; color: var(--ink);
    }
    .mini:hover { border-color: var(--teal); color: var(--teal-dark); }
    .conn-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.3rem; }
    .conn-list li {
      font-family: var(--mono); font-size: 0.72rem; color: var(--muted);
      display: flex; flex-wrap: wrap; gap: 0.35rem; align-items: baseline;
    }
    .conn-list button {
      border: 0; background: none; color: var(--teal-dark);
      font: inherit; cursor: pointer; padding: 0; font-weight: 600;
    }
    .conn-list button:hover { text-decoration: underline; }
    .c-kind { color: var(--mid); font-size: 0.62rem; }
    .p-dim { color: var(--muted); font-size: 0.78rem; margin: 0; }

    footer.note {
      margin-top: 1.5rem; padding-top: 1rem;
      border-top: 1px solid var(--hair);
      font-family: var(--mono); font-size: 0.65rem; color: var(--muted);
      display: flex; flex-wrap: wrap; gap: 0.35rem; align-items: center;
    }
    footer.note img { width: 14px; height: 14px; }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation: none !important; transition: none !important;
      }
    }
  </style>
</head>
<body>
  <header class="bar" id="bar">
    <a class="bar-brand" href="https://telivity.app" aria-label="Telivity">
      <img src="assets/telivity/favicon.svg" width="22" height="22" alt="" />
      <span>Telivity</span>
    </a>
    <span class="bar-title">Agent connections</span>
    <span class="bar-meta">${graph.total_nodes} agents · ${graph.total_edges} edges</span>
  </header>

  <div class="shell">
    <section class="stage-wrap" id="stage">
      <div class="stage-head">
        <div>
          <h1>How agents <em>connect</em></h1>
          <p class="stage-sub">Pick a workflow. Watch the chain. Open any agent for its neighbors.</p>
        </div>
        <div class="wf-picker" role="group" aria-label="Workflows">
${wfSegs}
        </div>
      </div>

      <div class="chain-board" id="chain-board" data-wf="${escapeHtml(defaultWf)}">
        <div class="chain-label">Workflow path</div>
        <div class="chain-track" id="chain-track">
${seedStage || '          <p class="chain-empty">No workflow edges in the graph.</p>'}
        </div>
      </div>
    </section>

    <section class="roster" id="roster">
      <div class="roster-head">
        <div>
          <h2>All agents</h2>
          <p>Stages light up when they sit on the active path. Select an agent to inspect edges.</p>
        </div>
        <div class="controls">
          <input id="search" type="search" placeholder="Search id or name…" />
          <select id="stage-filter"><option value="all">All stages</option></select>
          <select id="status-filter">
            <option value="all">All status</option>
            <option value="active">Active</option>
            <option value="stub">Stub</option>
          </select>
        </div>
      </div>
      <div class="bento" id="bento">
${stageTiles}
      </div>
    </section>

    <footer class="note">
      <img src="assets/telivity/favicon.svg" width="14" height="14" alt="" />
      <span>Telivity Otaip</span>
      <span>·</span>
      <span>${graph.total_nodes} agents · ${graph.total_edges} edges · from <code>agents.graph.json</code></span>
    </footer>
  </div>

  <div class="scrim" id="scrim" hidden></div>
  <aside class="panel" id="panel" aria-hidden="true">
    <div class="panel-top"><button type="button" class="panel-x" id="panel-close" aria-label="Close">×</button></div>
    <div id="panel-content"></div>
  </aside>

  <script id="graph-data" type="application/json">${payload.replace(/</g, '\\u003c')}</script>
  <script>
    const data = JSON.parse(document.getElementById('graph-data').textContent);
    const nodesById = Object.fromEntries(data.nodes.map(n => [n.id, n]));
    const STAGE_NAMES = ${JSON.stringify(STAGE_DISPLAY)};
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    const bar = document.getElementById('bar');
    window.addEventListener('scroll', () => bar.classList.toggle('scrolled', window.scrollY > 8), { passive: true });

    let activeWf = data.defaultWorkflow || '';
    let selectedId = null;

    function escape(s) {
      return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }

    function pathIds() {
      if (!activeWf || !data.workflows[activeWf]) return new Set();
      return new Set(data.workflows[activeWf].chain);
    }

    function renderChain() {
      const track = document.getElementById('chain-track');
      const board = document.getElementById('chain-board');
      const meta = data.workflows[activeWf];
      board.dataset.wf = activeWf || '';
      if (!meta || !meta.chain.length) {
        track.innerHTML = '<p class="chain-empty">No agents on this workflow.</p>';
        return;
      }
      let html = '';
      meta.chain.forEach((id, i) => {
        const n = nodesById[id];
        if (!n) return;
        const sel = selectedId === id ? ' selected' : '';
        const conn = i < meta.chain.length - 1
          ? '<div class="conn" aria-hidden="true"><span class="conn-line"></span><span class="conn-arrow"></span></div>'
          : '';
        html += '<div class="chain-item" style="--i:' + i + '">'
          + '<button type="button" class="chain-card' + sel + '" data-id="' + escape(id) + '">'
          + '<span class="c-step">' + String(i + 1).padStart(2, '0') + '</span>'
          + '<span class="c-id">' + escape(id) + '</span>'
          + '<span class="c-name">' + escape(n.name) + '</span>'
          + '<span class="c-stage">' + escape(STAGE_NAMES[n.stage] || n.stage) + '</span>'
          + '</button>' + conn + '</div>';
      });
      track.innerHTML = html;
      for (const btn of track.querySelectorAll('.chain-card')) {
        btn.addEventListener('click', () => selectAgent(btn.dataset.id));
      }
    }

    function paintRoster() {
      const path = pathIds();
      const q = document.getElementById('search').value.trim().toLowerCase();
      const st = document.getElementById('stage-filter').value;
      const status = document.getElementById('status-filter').value;
      const neighbors = selectedId ? neighborSet(selectedId) : null;

      for (const tile of document.querySelectorAll('.tile')) {
        const stage = tile.dataset.stage;
        let anyVisible = false;
        let stageOnPath = false;
        for (const row of tile.querySelectorAll('.agent-row')) {
          const id = row.dataset.id;
          const n = nodesById[id];
          const matchQ = !q || id.includes(q) || n.name.toLowerCase().includes(q);
          const matchSt = st === 'all' || stage === st;
          const matchStatus = status === 'all' || n.contract_status === status;
          const show = matchQ && matchSt && matchStatus;
          row.hidden = !show;
          if (show) anyVisible = true;
          const on = path.has(id);
          if (on) stageOnPath = true;
          row.classList.toggle('on-path', on);
          row.classList.toggle('selected', selectedId === id);
          row.classList.toggle('dim', Boolean(selectedId) && selectedId !== id && !(neighbors && neighbors.has(id)));
        }
        tile.hidden = !anyVisible;
        tile.classList.toggle('on-path', stageOnPath && activeWf);
        tile.classList.toggle('dim', Boolean(activeWf) && !stageOnPath);
      }
    }

    function neighborSet(id) {
      const s = new Set();
      for (const e of data.edges) {
        if (e.source === id) s.add(e.target);
        if (e.target === id) s.add(e.source);
      }
      return s;
    }

    function workflowsFor(id) {
      const set = new Set();
      for (const e of data.edges) {
        if (e.kind === 'workflow' && (e.source === id || e.target === id)) set.add(e.label);
      }
      return [...set].sort();
    }

    function neighbors(id) {
      const up = [], down = [];
      for (const e of data.edges) {
        if (e.source === id) down.push(e);
        if (e.target === id) up.push(e);
      }
      return { up, down };
    }

    const panel = document.getElementById('panel');
    const scrim = document.getElementById('scrim');
    const panelContent = document.getElementById('panel-content');
    let panelOpen = false;

    function openPanel(id) {
      const n = nodesById[id];
      if (!n) return;
      const wfs = workflowsFor(id);
      const nb = neighbors(id);
      let html = '<div class="p-id">' + escape(n.id) + '</div>';
      html += '<h3>' + escape(n.name) + '</h3>';
      html += '<div class="badge' + (n.contract_status === 'stub' ? ' stub' : '') + '"><i></i>' + escape(n.contract_status) + '</div>';
      html += '<dl>';
      html += '<dt>Stage</dt><dd>' + escape(STAGE_NAMES[n.stage] || n.stage) + '</dd>';
      html += '<dt>Version</dt><dd>' + escape(n.version) + '</dd>';
      html += '<dt>Contract</dt><dd>' + (n.has_contract ? 'Yes' : 'No') + '</dd>';
      html += '<dt>Source</dt><dd><code>' + escape(n.source_path) + '</code></dd>';
      html += '</dl>';
      html += '<div class="p-label">Workflows</div>';
      if (wfs.length) {
        html += '<div class="mini-row">';
        for (const w of wfs) html += '<button type="button" class="mini" data-wf-jump="' + escape(w) + '">' + escape(w) + '</button>';
        html += '</div>';
      } else html += '<p class="p-dim">Not in a built-in workflow.</p>';
      html += '<div class="p-label">Connections</div><ul class="conn-list">';
      for (const e of nb.up) {
        html += '<li><span>&larr;</span> <button type="button" data-jump="' + escape(e.source) + '">' + escape(e.source) + '</button> <span class="c-kind">' + escape(e.kind === 'workflow' ? e.label : 'package') + '</span></li>';
      }
      for (const e of nb.down) {
        html += '<li><span>&rarr;</span> <button type="button" data-jump="' + escape(e.target) + '">' + escape(e.target) + '</button> <span class="c-kind">' + escape(e.kind === 'workflow' ? e.label : 'package') + '</span></li>';
      }
      if (!nb.up.length && !nb.down.length) html += '<li class="p-dim">No graph edges.</li>';
      html += '</ul>';
      panelContent.innerHTML = html;
      panel.classList.add('open');
      panel.setAttribute('aria-hidden', 'false');
      scrim.hidden = false;
      requestAnimationFrame(() => scrim.classList.add('show'));
      panelOpen = true;
    }
    function closePanel() {
      if (!panelOpen) return;
      panel.classList.remove('open');
      panel.setAttribute('aria-hidden', 'true');
      scrim.classList.remove('show');
      panelOpen = false;
      setTimeout(() => { if (!panelOpen) scrim.hidden = true; }, 300);
    }
    document.getElementById('panel-close').addEventListener('click', closePanel);
    scrim.addEventListener('click', closePanel);
    document.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') closePanel(); });

    panelContent.addEventListener('click', (ev) => {
      const jump = ev.target.closest('[data-jump]');
      if (jump) { selectAgent(jump.dataset.jump); return; }
      const wf = ev.target.closest('[data-wf-jump]');
      if (wf) {
        setWorkflow(wf.dataset.wfJump);
        closePanel();
        document.getElementById('stage').scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth' });
      }
    });

    function selectAgent(id) {
      selectedId = id;
      renderChain();
      paintRoster();
      openPanel(id);
    }

    function setWorkflow(w) {
      activeWf = w;
      for (const seg of document.querySelectorAll('.wf-seg')) {
        const on = seg.dataset.workflow === w;
        seg.classList.toggle('active', on);
        seg.setAttribute('aria-pressed', on ? 'true' : 'false');
      }
      renderChain();
      paintRoster();
    }

    for (const seg of document.querySelectorAll('.wf-seg')) {
      seg.addEventListener('click', () => setWorkflow(seg.dataset.workflow));
    }

    for (const head of document.querySelectorAll('.tile-head')) {
      head.addEventListener('click', () => {
        const tile = head.closest('.tile');
        const open = tile.classList.toggle('open');
        head.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
    }
    for (const row of document.querySelectorAll('.agent-row')) {
      row.addEventListener('click', (ev) => {
        ev.stopPropagation();
        selectAgent(row.dataset.id);
      });
    }

    const stageEl = document.getElementById('stage-filter');
    for (const tile of document.querySelectorAll('.tile')) {
      const o = document.createElement('option');
      o.value = tile.dataset.stage;
      o.textContent = tile.querySelector('.tile-stage').textContent;
      stageEl.appendChild(o);
    }
    document.getElementById('search').addEventListener('input', paintRoster);
    stageEl.addEventListener('change', paintRoster);
    document.getElementById('status-filter').addEventListener('change', paintRoster);

    // seed chain card clicks + path highlight
    for (const btn of document.querySelectorAll('#chain-track .chain-card')) {
      btn.addEventListener('click', () => selectAgent(btn.dataset.id));
    }
    paintRoster();
  </script>
</body>
</html>
`;
}

function main(): void {
  const repo = repoRoot();
  const graphPath = join(repo, GRAPH_PATH);
  if (!existsSync(graphPath)) {
    console.error(`${GRAPH_PATH} missing. Run \`pnpm gen:manifest\` first.`);
    process.exit(1);
  }
  const graph = JSON.parse(readFileSync(graphPath, 'utf8')) as AgentGraph;
  const html = renderAgentMapHtml(graph);
  const out = join(repo, MAP_HTML_PATH);
  writeFileSync(out, html);
  console.log(`Wrote ${MAP_HTML_PATH} (${graph.total_nodes} agents).`);
}

const isDirect =
  process.argv[1] !== undefined &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (isDirect) {
  main();
}
